from django.http import JsonResponse

DISCOUNT_CODES = {'SAVE10': 0.10, 'SAVE25': 0.25}


def price(request):
    try:
        amount = float(request.GET.get('amount', ''))
    except ValueError:
        return JsonResponse({'error': 'amount must be a number'}, status=400)
    if amount < 0:
        return JsonResponse({'error': 'amount must be non-negative'}, status=400)
    rate = DISCOUNT_CODES.get(request.GET.get('code', ''), 0.0)
    return JsonResponse({'amount': amount, 'discount': rate, 'total': round(amount * (1 - rate), 2)})
